#pragma once

#include <vector>

namespace mixxx {
namespace android {

// Autonomously generated by an AI agent.
// After a USB hotplug the device id may change index. Returns the single
// available device with the saved name. Keeps the saved id when no device or
// several devices share that name, so the restore never guesses.
// End of comment autonomously generated by an AI agent.
template<typename DeviceId>
DeviceId resolveRecoveredDeviceId(const DeviceId& saved, const std::vector<DeviceId>& available) {
    const DeviceId* match = nullptr;
    for (const auto& id : available) {
        if (id.name != saved.name) {
            continue;
        }
        if (match) {
            return saved;
        }
        match = &id;
    }
    return match ? *match : saved;
}

} // namespace android
} // namespace mixxx
